from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Loop through the input string to identify and extract separate groups of nested parentheses
    groups = []
    start = 0
    stack = []

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                groups.append(paren_string[start:i+1])

    # Step 3: Check if each extracted group is balanced using a stack data structure
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    # Step 4: Store the balanced groups in a list and return the list
    return [group for group in groups if is_balanced(group)]

